import datetime

class FinancialSystem:
    def __init__(self):
        self.accounts = {}
        self.trades = []
        self.fees = {
            'deposit': 0.1,
            'withdrawal': 0.1,
            'transfer': 0.05,
            'buy': 0.02,
            'sell': 0.03
        }
        self.reporting_methods = {
            'daily': self.daily_report,
            'weekly': self.weekly_report,
            'monthly': self.monthly_report
        }

    def create_account(self, account_id, initial_balance=0):
        if account_id in self.accounts:
            raise ValueError("Account already exists")
        self.accounts[account_id] = {'balance': initial_balance}

    def deposit(self, account_id, amount):
        if account_id not in self.accounts:
            raise ValueError("Account does not exist")
        self.accounts[account_id]['balance'] += amount
        self.process_transaction(account_id, 'deposit', amount)

    def withdraw(self, account_id, amount):
        if account_id not in self.accounts:
            raise ValueError("Account does not exist")
        if self.accounts[account_id]['balance'] < amount:
            raise ValueError("Insufficient funds")
        self.accounts[account_id]['balance'] -= amount
        self.process_transaction(account_id, 'withdrawal', amount)

    def transfer(self, from_account_id, to_account_id, amount):
        if from_account_id not in self.accounts or to_account_id not in self.accounts:
            raise ValueError("Accounts do not exist")
        if self.accounts[from_account_id]['balance'] < amount:
            raise ValueError("Insufficient funds")
        self.accounts[from_account_id]['balance'] -= amount
        self.accounts[to_account_id]['balance'] += amount
        self.process_transaction(from_account_id, 'transfer', amount)
        self.process_transaction(to_account_id, 'transfer', amount)

    def buy(self, account_id, symbol, quantity, price):
        if account_id not in self.accounts:
            raise ValueError("Account does not exist")
        cost = quantity * price
        if self.accounts[account_id]['balance'] < cost:
            raise ValueError("Insufficient funds")
        self.accounts[account_id]['balance'] -= cost
        self.process_transaction(account_id, 'buy', cost)

    def sell(self, account_id, symbol, quantity, price):
        if account_id not in self.accounts:
            raise ValueError("Account does not exist")
        revenue = quantity * price
        if self.accounts[account_id]['balance'] < revenue:
            raise ValueError("Insufficient funds")
        self.accounts[account_id]['balance'] += revenue
        self.process_transaction(account_id, 'sell', revenue)

    def process_transaction(self, account_id, action, amount):
        transaction = {
            'timestamp': datetime.datetime.now(),
            'account_id': account_id,
            'action': action,
            'amount': amount
        }
        self.trades.append(transaction)
        self.apply_fees(action, amount)

    def apply_fees(self, action, amount):
        fee = self.fees[action] * abs(amount)
        if action == 'deposit' or action == 'withdrawal':
            self.accounts[transaction['account_id']]['balance'] -= fee
        elif action == 'transfer':
            self.accounts[transaction['from_account_id']]['balance'] -= fee
            self.accounts[transaction['to_account_id']]['balance'] -= fee
        elif action == 'buy' or action == 'sell':
            self.accounts[transaction['account_id']]['balance'] += fee

    def daily_report(self):
        return self.generate_report('daily')

    def weekly_report(self):
        return self.generate_report('weekly')

    def monthly_report(self):
        return self.generate_report('monthly')

    def generate_report(self, frequency):
        report_data = []
        for trade in self.trades:
            if trade['frequency'] == frequency:
                report_data.append({
                    'timestamp': trade['timestamp'],
                    'account_id': trade['account_id'],
                    'action': trade['action'],
                    'amount': trade['amount']
                })
        return report_data
