    def __init__(self, order_id, symbol, side, quantity, price, order_type, status, timestamps, fills):
        self.order_id = order_id
        self.symbol = symbol
        self.side = side
        self.quantity = quantity
        self.price = price
        self.order_type = order_type
        self.status = status
        self.timestamps = timestamps
        self.fills = fills

    @property
    def total_value(self):
        return self.quantity * self.price

    @property
    def average_price(self):
        if not self.fills:
            return None
        return sum(fill['price'] for fill in self.fills) / len(self.fills)

    @property
    def filled_quantity(self):
        return sum(fill['quantity'] for fill in self.fills)

    @property
    def unfilled_quantity(self):
        return self.quantity - self.filled_quantity

    @property
    def fill_rate(self):
        if not self.fills:
            return 0
        return self.filled_quantity / self.quantity

    @property
    def fill_time(self):
        if not self.fills:
            return None
        return min(fill['timestamp'] for fill in self.fills)
