    return sum(item['price'] * item['quantity'] for item in items)

def apply_discount(total_price, discount_rate):
    """Apply a discount to the total price based on the given rate."""
    if discount_rate > 1:
        raise ValueError("Discount rate cannot exceed 100%")
    return total_price * (1 - discount_rate / 100)

def process_order(order_items, discount_rate=0):
    """Process an e-commerce order by calculating total price and applying discount."""
