    def calculate_total_price(self, order):
        # Calculate the total price of the order based on item prices and quantities
        total_price = sum(item['price'] * item['quantity'] for item in order['items'])
        order['total_price'] = total_price
        return total_price

    def update_inventory(self, order):
        # Update the inventory after processing the order
        for item in order['items']:
            self.inventory[item['product']] -= item['quantity']

    def process_payment(self, order, payment_method):
